    }

public class PaymentStatusManager {
    private String status = "open";

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }
}

// Usage in the Order processors

public class PaypalPaymentProcessor implements PaymentProcessor {
    private PaymentStatusManager paymentStatusManager;

    public PaypalPaymentProcessor(PaymentStatusManager paymentStatusManager) {
        this.paymentStatusManager = paymentStatusManager;
    }

    @Override
    public void pay(Order order, String securityCode) {
        System.out.println("Processing paypal payment");
        System.out.println("Verifying email: " + securityCode);
        paymentStatusManager.setStatus("paid");
    }
}

